import{_ as l,l as n,o as e,c as s,v as r,p as o,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"前缀和与差分","description":"","frontmatter":{"title":"前缀和与差分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prefix-sum-difference.md","filePath":"cs/prefix-sum-difference.md","lastUpdated":1789023840000}'),h={name:"cs/prefix-sum-difference.md"};function m(f,a,_,A,u,S){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="前缀和与差分" tabindex="-1">前缀和与差分 <a class="header-anchor" href="#前缀和与差分" aria-label="Permalink to &quot;前缀和与差分&quot;">​</a></h1><div class="epigraph"><p>把每个位置改成「从左端扫到这里的合计」，区间和就变成两次查表相减；差分是它的逆运算，把区间加变成两端各改一次。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Sedgewick and Wayne, Algorithms 整理</footer></div><p><a href="/cs/cache-side-channel">上一课</a>把微结构进阶收到 cache 组相联的副作用上。主干里<a href="/cs/array-random-access">数组与随机访问</a>已经给出按下标 \\(\\Theta(1)\\) 读写，但没有把「一段连续下标的合计」收成预处理结构。本课起数据结构进阶：不重开推测执行，也不重讲地址公式。缺口是：静态数组上的区间和、以及区间加完再读点值——用前缀和与差分数组，而不是每次扫描。后课默认已经读完这里：静态区间和是 \\(O(1)\\) 查询，\\(O(n)\\) 预处理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 元数组 \\(A\\)，多次问 \\(\\sum_{i=l}^{r} A[i]\\)。每次扫 \\([l,r]\\) 是 \\(\\Theta(r-l+1)\\)，查询多了不可接受。缺口不是新的存储模型，而是<strong>一次从左到右的合计表</strong> \\(S[i]=\\sum_{j=1}^{i}A[j]\\)（\\(S[0]=0\\)），使</p> \\[\\sum_{i=l}^{r} A[i] = S[r]-S[l-1]. \\]<p>对偶问题：多次对 \\([l,r]\\) 同时加 \\(d\\)，最后读每个点。若每次把区间扫一遍，总代价随更新长度涨。差分 \\(D[1]=A[1]\\)，\\(D[i]=A[i]-A[i-1]\\)（\\(i\\gt 1\\)）把区间加变成 \\(D[l]\\mathrel{+}=d\\)、\\(D[r+1]\\mathrel{-}=d\\)，再前缀和还原 \\(A\\)。</p><p><span class="marginnote">前缀和是扫描的记录；差分是离散导数。二维前缀和（容斥四角）同构，本课先钉一维，后课线段树再谈可变数组。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理：从左扫一遍写 \\(S\\)，时间 \\(\\Theta(n)\\)，额外 \\(\\Theta(n)\\) 字。查询两次随机访问。差分更新：合法下标上两次写；全部更新结束后对 \\(D\\) 做一次前缀和得到最终 \\(A\\)。不要在「尚未还原」的 \\(D\\) 上直接当点值用，除非合同写明读的是差分数组本身。</p>',10)),(e(),o(p,null,{default:t(()=>[c(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%20A%22%5D%20--%3E%20S%5B%22%E5%89%8D%E7%BC%80%E5%92%8C%20S%22%5D%0A%20%20S%20--%3E%20Q%5B%22S%5Br%5D%20-%20S%5Bl-1%5D%22%5D%0A%20%20D%5B%22%E5%B7%AE%E5%88%86%20D%22%5D%20--%3E%20A2%5B%22%E5%89%8D%E7%BC%80%E8%BF%98%E5%8E%9F%20A%22%5D%0A%20%20U%5B%22%E5%8C%BA%E9%97%B4%E5%8A%A0%22%5D%20--%3E%20D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/cs/amortized-analysis">摊还分析</a>无关：这里每次查询最坏已是 \\(\\Theta(1)\\)，没有峰值要摊。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性就是和的结合律与减法消去。下标约定必须全局一致：从 \\(0\\) 还是从 \\(1\\)，以及空区间 \\(l\\gt r\\) 是否定义为 \\(0\\)。溢出：合计宽度要能装下 \\(n\\) 倍元素上界，否则环绕会把区间和证伪。</p><p>差分与前缀互逆：对 \\(A\\) 取差分再前缀，得到 \\(A\\)；对 \\(D\\) 取前缀再差分，得到 \\(D\\)。区间加只动两端，是因为中间的差分不变——相邻差没变，整段被抬高同一常数。</p><p>顺序扫写 \\(S\\) 吃<a href="/cs/locality-principle">局部性</a>；查询两次随机读，cache 行为取决于 \\(l,r\\) 是否跳。本课不把这当成外存 B 树问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>前缀和要求<strong>可结合、有逆</strong>的区间贡献（通常是加法群）。最大值、最大公因数没有群逆，不能靠两次查表相减得到任意区间——那是下一课稀疏表的入口。数组中途被单点改掉，\\(S\\) 全表作废，需要树状数组或线段树，本课不提前写。</p><p>后课默认：静态加法区间用前缀和；静态幂等查询另找倍增表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀和：\\(O(n)\\) 预处理，\\(O(1)\\) 区间和。</li><li>差分：区间加变成两端点更新，再前缀还原。</li><li>需要群运算；无逆的聚合留给稀疏表。</li><li>出处：Cormen et al.；Sedgewick and Wayne。</li></ul>',10))])}const B=l(h,[["render",m]]);export{E as __pageData,B as default};
